fn safe_index(v: &Vec[Int], index: Int) -> Int
  requires: index >= 0;
  requires: index < v.len();
  ensures: result == v[index];
{
  return v[index];
}

fn main() -> Int {
  let data = Vec[Int]();
  data.push(10);
  data.push(20);
  data.push(30);
  return safe_index(&data, 1);
}
